    const name = formData.get('name')
    const email = formData.get('email')
    const message = formData.get('message')

    // Server-side validation: never trust client-side checks alone
    const missing: string[] = []
    if (typeof name !== 'string' || name.trim() === '') missing.push('name')
    if (typeof email !== 'string' || email.trim() === '') missing.push('email')
    if (typeof message !== 'string' || message.trim() === '') {
      missing.push('message')
    }

    if (missing.length > 0) {
      throw new Error(`Missing required field(s): ${missing.join(', ')}`)
    }

    const contactMessage = {
      name: (name as string).trim(),
      email: (email as string).trim(),
      message: (message as string).trim(),
    }

    // Simulate saving the contact message
    console.log('Saving contact message:', contactMessage)
  }

  return (
    <div>
      <h2>Contact Us</h2>
      <form action={saveContactMessage}>
